# Harold's blocked calendar intervals (start, end). Jeffrey is free throughout.
busy = {
    "Harold": {
        "Monday": [(to_minutes("09:00"), to_minutes("10:00")),
                   (to_minutes("10:30"), to_minutes("17:00"))],
        "Tuesday": [(to_minutes("09:00"), to_minutes("09:30")),
                    (to_minutes("10:30"), to_minutes("11:30")),
