    },
    "Jeffrey": {
        "Monday": [],
        "Tuesday": [],
    },
}

def is_free(day, start, end, participants):
    return all(
        not (s < end and start < e)
        for participant in participants
        for s, e in busy[participant][day]
    )

# Harold's stated preferences: avoid more meetings on Monday, and avoid Tuesday before 14:30.
# These are handled as filters on the generated candidate slots.

def acceptable(day, start, end):
    if not is_free(day, start, end, ("Harold", "Jeffrey")):
        return False
    if day == "Monday":
        return False
    if day == "Tuesday" and start < to_minutes("14:30"):
