# Variables: meeting day, start minute, end minute.
DAY = "Monday"
WORK_START = to_minutes("09:00")
WORK_END = to_minutes("17:00")
DURATION_MINUTES = 30

# Each participant's fixed busy intervals, in minutes.
BUSY_INTERVALS = {
    "Judy": [],
    "Nicole": [
        (to_minutes("09:00"), to_minutes("10:00")),
        (to_minutes("10:30"), to_minutes("16:30")),
    ],
}

# Preference: Nicole does not want the meeting to start before 16:00.
