    "Nicole": {"earliest_start": to_minutes("16:00")},
}

def is_feasible(start, end):
    if start < WORK_START or end > WORK_END:
        return False
    if end - start != DURATION_MINUTES:
        return False
    for intervals in BUSY_INTERVALS.values():
        for busy_start, busy_end in intervals:
            if start < busy_end and busy_start < end:
                return False
    for prefs in PREFERENCES.values():
        if start < prefs.get("earliest_start", WORK_START):
            return False
    return True

solution = None
latest_start = WORK_END - DURATION_MINUTES
for start in range(WORK_START, latest_start + 1):
    end = start + DURATION_MINUTES
    if is_feasible(start, end):
        solution = [DAY, to_time_string(start), to_time_string(end)]
        break

if solution is None:
    raise RuntimeError("No feasible time found")

