# - Domain: Monday 09:00 <= start and end <= 17:00.
# - Constraint: [start, end) must not overlap any busy interval.
# - Objective: choose earliest start satisfying all constraints.

def to_minutes(time_str):
    hours, minutes = map(int, time_str.split(":"))
    return hours * 60 + minutes

def to_hhmm(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

DAY = "Monday"
WORK_START = to_minutes("09:00")
WORK_END = to_minutes("17:00")
DURATION = to_minutes("00:30")
PARTICIPANTS = ["Adam", "Roy"]

BUSY = {
    "Adam": [
        ("09:30", "10:00"),
        ("12:30", "13:00"),
        ("14:30", "15:00"),
        ("16:30", "17:00"),
    ],
    "Roy": [
        ("10:00", "11:00"),
        ("11:30", "13:00"),
        ("13:30", "14:30"),
        ("16:30", "17:00"),
    ],
}

BUSY_MINUTES = {}
for person, intervals in BUSY.items():
    BUSY_MINUTES[person] = [
        (to_minutes(start), to_minutes(end)) for start, end in intervals
    ]

def is_free(person, start, end):
    return all(
        end <= busy_start or start >= busy_end
        for busy_start, busy_end in BUSY_MINUTES[person]
    )

def find_earliest_meeting():
    for start in range(WORK_START, WORK_END - DURATION + 1):
        end = start + DURATION
        if all(is_free(person, start, end) for person in PARTICIPANTS):
            return [DAY, to_hhmm(start), to_hhmm(end)]
    return None

print(find_earliest_meeting())

