# CSP formalization:
# Variables: day, start_minutes, end_minutes (minutes after midnight).
# Constraints:
#   - day must be Monday through Friday.
#   - meeting must lie within work hours 09:00-17:00.
#   - meeting duration is 60 minutes.
#   - meeting must not overlap any participant's busy interval.
#   - Matthew prefers no Wednesday meeting before 12:30.

DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
WORK_START = 9 * 60
WORK_END = 17 * 60
DURATION = 60
WEDNESDAY_EARLIEST = 12 * 60 + 30

BUSY = {
    "Diane": {
        "Monday": [(12 * 60, 12 * 60 + 30), (15 * 60, 15 * 60 + 30)],
        "Tuesday": [(10 * 60, 11 * 60), (11 * 60 + 30, 12 * 60),
                    (12 * 60 + 30, 13 * 60), (16 * 60, 17 * 60)],
        "Wednesday": [(9 * 60, 9 * 60 + 30), (14 * 60 + 30, 15 * 60),
                      (16 * 60 + 30, 17 * 60)],
