        "Monday": [(9 * 60, 10 * 60), (10 * 60 + 30, 17 * 60)],
        "Tuesday": [(9 * 60, 17 * 60)],
        "Wednesday": [(9 * 60, 11 * 60), (12 * 60, 14 * 60 + 30),
                      (16 * 60, 17 * 60)],
        "Thursday": [(9 * 60, 16 * 60)],
        "Friday": [(9 * 60, 17 * 60)],
    },
}

def overlaps(start, end, busy_start, busy_end):
    return start < busy_end and busy_start < end

def is_free(day, start, end):
    if start < WORK_START or end > WORK_END:
        return False

    if day == "Wednesday" and start < WEDNESDAY_EARLIEST:
        return False

    for person_events in BUSY.values():
        for busy_start, busy_end in person_events[day]:
            if overlaps(start, end, busy_start, busy_end):
                return False

    return True

