# Variables: day, start, end. Times are integer minutes since midnight.
DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday"]
WORK_START = minutes(9)
WORK_END = minutes(17)
DURATION = 30

# Cheryl's calendar is open, so James's meetings are the only occupied slots.
JAMES_MEETINGS = {
    "Monday": [
        (minutes(9), minutes(9, 30)),
        (minutes(10, 30), minutes(11)),
        (minutes(12, 30), minutes(13)),
        (minutes(14, 30), minutes(15, 30)),
        (minutes(16, 30), minutes(17)),
    ],
    "Tuesday": [
        (minutes(9), minutes(11)),
        (minutes(11, 30), minutes(12)),
        (minutes(12, 30), minutes(15, 30)),
        (minutes(16), minutes(17)),
    ],
    "Wednesday": [
        (minutes(10), minutes(11)),
        (minutes(12), minutes(13)),
        (minutes(13, 30), minutes(16)),
    ],
    "Thursday": [
        (minutes(9, 30), minutes(11, 30)),
        (minutes(12), minutes(12, 30)),
        (minutes(13), minutes(13, 30)),
        (minutes(14), minutes(14, 30)),
        (minutes(16, 30), minutes(17)),
    ],
}

# Cheryl prefers not to meet on Wednesday or Thursday.
BLOCKED_DAYS = {"Wednesday", "Thursday"}

def format_time(t):
    return "{:02d}:{:02d}".format(t // 60, t % 60)

def find_earliest_slot():
    for day in DAYS:
        if day in BLOCKED_DAYS:
            continue

        for start in range(WORK_START, WORK_END - DURATION + 1):
            end = start + DURATION

            overlaps = any(
                start < busy_end and busy_start < end
                for busy_start, busy_end in JAMES_MEETINGS.get(day, [])
            )

            if not overlaps:
                return [day, format_time(start), format_time(end)]

    raise RuntimeError("No available slot found")

if __name__ == "__main__":
    print(find_earliest_slot())

# Meeting scheduling as a small CSP.
# Variables: (day, start_minute)
# Domain: Monday/Tuesday/Wednesday; start in [9:00, 17:00) such that the
# 30-minute meeting ends no later than 17:00.
# Constraint: the interval must not overlap any existing busy interval.

WORK_START = 9 * 60
WORK_END = 17 * 60
MEETING_DURATION = 30

DAYS = ["Monday", "Tuesday", "Wednesday"]

BUSY = {
    "Larry": {
        "Monday": [],
        "Tuesday": [],
        "Wednesday": [],
    },
    "Samuel": {
        "Monday": [
            (10 * 60 + 30, 11 * 60),
            (12 * 60, 12 * 60 + 30),
            (13 * 60, 15 * 60),
            (15 * 60 + 30, 16 * 60 + 30),
        ],
        "Tuesday": [
            (9 * 60, 12 * 60),
            (14 * 60, 15 * 60 + 30),
            (16 * 60 + 30, 17 * 60),
        ],
        "Wednesday": [
            (10 * 60 + 30, 11 * 60),
            (11 * 60 + 30, 12 * 60),
            (12 * 60 + 30, 13 * 60),
            (14 * 60, 14 * 60 + 30),
            (15 * 60, 16 * 60),
        ],
    },
}

def is_free(person, day, start):
    meeting_end = start + MEETING_DURATION
    for busy_start, busy_end in BUSY[person][day]:
        if start < busy_end and meeting_end > busy_start:
            return False
    return True

def format_minutes(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

def main():
    for day in DAYS:
        for start in range(WORK_START, WORK_END, MEETING_DURATION):
            if all(is_free(person, day, start) for person in BUSY):
                print([day, format_minutes(start), format_minutes(start + MEETING_DURATION)])
                return

main()
